#include "isr.h"
#include "sio_uart_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void sio_uart_irq_service (Sio_Uart sio_uart)
{
  /// Determine source if interrupt and service \\\

  switch (sio_uart->uart_reg [UIIR] & 0x0F)
    {
      case 0x04 : // RDA - (R)eceiver  (D)ata    (A)vailable 
      case 0x0C : // CTI - (C)haracter (T)imeout (I)ndicator 
        {
          sio_uart_irq_service_rx (sio_uart) ;

          break ;
        }

      case 0x02 : // THRE - (T)ransmitter (H)olding (R)egister (E)mpty 
        {
          sio_uart_irq_service_tx (sio_uart) ;

          break ;
        }

      case 0x06 : // RLS - (R)eceive (L)ine (S)tatus 
        {
          sio_uart_irq_service_rls (sio_uart) ;

          break ;
        }
    }
}

